    // **绝不因为时间认错过而让她什么也找不到。**
    let narrowed = null;
    const timeHint = parseTimeHint(query, Date.now());
    if (timeHint !== null) {
      const inWindow = all.filter(
        (e) => Number.isFinite(e.created_at) && e.created_at >= timeHint.from && e.created_at <= timeHint.to,
